#!/usr/bin/env python3
"""Regenerate qml/IconData.js from assets/icons/*.svg."""

import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
icons = {}
for path in sorted((root / "assets/icons").glob("*.svg")):
    icons[path.stem] = path.read_text()

lines = [
    "// Generated by scripts/gen-icons.py. Do not edit.",
    ".pragma library",
    "",
    "var data = {",
]
for name, svg in icons.items():
    lines.append(f"  {json.dumps(name)}: {json.dumps(svg)},")
lines += [
    "};",
    "",
    "var cache = {};",
    "",
    "function source(name, color) {",
    '    var key = name + "|" + color;',
    "    if (cache[key]) return cache[key];",
    "    var svg = data[name];",
    '    if (!svg) return "";',
    "    var tinted = svg",
    "        .replace(/currentColor/g, color)",
    "        .replace(/#ffffff/gi, color)",
    "        .replace(/#fff/gi, color)",
    "        .replace(/#000000/gi, color)",
    "        .replace(/#000/gi, color);",
    '    var url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(tinted);',
    "    cache[key] = url;",
    "    return url;",
    "}",
    "",
]
(root / "qml/IconData.js").write_text("\n".join(lines))
print(f"wrote qml/IconData.js with {len(icons)} icons")
